258: func raiseGreenhouseNotice(ctx context.Context, db *store.DB, project store.Project, task store.Task, snapshot greenhouseWatchSnapshot, previous, current string) error {
259: 	kind, summary := "", ""
260: 	stage, _ := greenhouseStageLabel(snapshot)
261: 	switch current {
262: 	case "needs-decision":
263: 		kind, summary = "greenhouse_decision_needed", task.Title+": Greenhouse needs a decision"
264: 	case "failed", "recovery-required":
265: 		kind, summary = "greenhouse_failed", task.Title+": Greenhouse failed: "+stage
266: 	case "ci-ready", "locally-ready":
267: 		kind, summary = "greenhouse_pr_green", task.Title+": Greenhouse pipeline is green"
268: 	}
269: 	if kind == "" || previous == current {
270: 		return nil
271: 	}
272: 	_, err := db.CreateNotice(ctx, store.Notice{ProjectID: project.ID, TaskID: task.ID, Kind: kind, Summary: summary, DataJSON: marshalJSON(map[string]any{"run_id": snapshot.RunID, "stage": stage})})
273: 	return err
274: }
