276: func inspectGreenhouseRun(ctx context.Context, task store.Task, runID string) greenhouseWatchSnapshot {
277: 	request, _ := json.Marshal(map[string]any{"version": 2, "op": "inspect", "run_id": runID})
278: 	command := exec.CommandContext(ctx, "greenhouse", "axi")
279: 	command.Dir = task.WorktreePath
280: 	command.Stdin = bytes.NewReader(request)
281: 	command.Env = os.Environ()
282: 	output, err := command.Output()
283: 	if err != nil {
284: 		return greenhouseWatchSnapshot{}
285: 	}
286: 	var snapshot greenhouseWatchSnapshot
287: 	if json.Unmarshal(output, &snapshot) != nil {
288: 		return greenhouseWatchSnapshot{}
289: 	}
290: 	if snapshot.RunID == "" {
291: 		snapshot.RunID = snapshot.Run.ID
292: 	}
293: 	return snapshot
294: }
