42: 	}
43: 	var legacy greenhouseWatchSnapshot
44: 	if err := json.Unmarshal([]byte(`{"run":{"started_at":"`+started+`","pipeline":{"stages":[{"name":"review","status":"running"}]}}}`), &legacy); err != nil {
45: 		t.Fatal(err)
46: 	}
47: 	legacyRun, legacyStage, legacyFinished := greenhouseStageTimestamps(legacy, "review")
48: 	if legacyRun != wantRun || legacyStage != 0 || legacyFinished != 0 {
49: 		t.Fatalf("timestamp-less stage = %d/%d/%d, want run time and observation fallbacks", legacyRun, legacyStage, legacyFinished)
50: 	}
51: 	watch := store.GreenhouseTaskWatch{Stage: "review", RunObservedAt: greenhouseTimestampMillis(started), StageObservedAt: greenhouseTimestampMillis(stageStarted)}
52: 	if got := greenhouseElapsedSummary(watch, time.UnixMilli(greenhouseTimestampMillis(stageStarted)+3*60*1000)); got != "review 3m · run 5m" {
53: 		t.Fatalf("legacy elapsed summary = %q", got)
54: 	}
55: }
