37: 		if err == nil {
38: 			var pid int
39: 			if json.Unmarshal(contents, &pid) == nil && pid > 1 {
40: 				executable, err := os.Readlink(filepath.Join("/proc", strconv.Itoa(pid), "exe"))
41: 				if err != nil {
42: 					t.Fatalf("read Greenhouse daemon executable for PID %d: %v", pid, err)
43: 				}
44: 				want, _ := filepath.EvalSymlinks(binary)
45: 				got, _ := filepath.EvalSymlinks(executable)
